blockquote {
	border: none;
	font-weight: 400;
	font-size: 2rem;
	max-width: 600px;
	line-height: 1.4;
	position: relative;
	margin: 0;
	padding: .5rem;
 font-family: Georgia, "Proxima-nova", Times, serif;}

blockquote:before,
blockquote:after {
	position: absolute;
	color: #003049;
	font-size: 8rem;
	width: 4rem;
	height: 4rem;
}

blockquote:before {
	content: '“';
	left: -5rem;
	top: -2rem;
}

blockquote:after {
	content: '”';
	right: -2rem;
	bottom: 1rem;
}

