/* Remove all WPForms extra borders/lines */
div.wpforms-container .wpforms-field,
div.wpforms-container .wpforms-field-row,
div.wpforms-container .wpforms-field-container,
div.wpforms-container .wpforms-field::before,
div.wpforms-container .wpforms-field::after {
    border: none !important;
    box-shadow: none !important;
}

/* Single clean border */
div.wpforms-container .wpforms-form input,
div.wpforms-container .wpforms-form textarea,
div.wpforms-container .wpforms-form select {
    border: 1px solid #e5e5e5 !important;
    border-bottom: 1px solid #e5e5e5 !important;
    background: transparent !important;
    border-radius: 0 !important;
    outline: none !important;
    box-shadow: none !important;
}

/* Keep same border on focus */
div.wpforms-container .wpforms-form input:focus,
div.wpforms-container .wpforms-form textarea:focus,
div.wpforms-container .wpforms-form select:focus {
    border: 1px solid #e5e5e5 !important;
    border-bottom: 1px solid #e5e5e5 !important;
    outline: none !important;
    box-shadow: none !important;
}

/* Left align submit button */
div.wpforms-container .wpforms-submit-container {
    text-align: left !important;
}

/* Optional: remove float if applied */
div.wpforms-container .wpforms-form button[type="submit"].wpforms-submit {
    float: none !important;
    margin-left: 0 !important;
}

